/* Harvest offers share the market with seeds and equipment. */
const materialsSellBeforeProduce=demoSell;
demoSell=function(){modalForm('Что выставим на рынок?',`<div class="room-theme-choice"><button type="button" onclick="sellStoredProduce()"><span>🧺</span>Урожай</button><button type="button" onclick="materialsSellBeforeProduce()"><span>🌱</span>Семена и материалы</button></div>`,()=>{})};
function sellStoredProduce(){if(!hasStorage()){openStorageSlot();return}if(ownFarm&&!ownFarm.visible){modalForm('Хозяйство скрыто',`<p>Чтобы продавать урожай, сначала покажите хозяйство на карте.</p><button type="button" class="btn" onclick="profileRoomVisibility()">Настроить видимость</button>`,()=>{});return}const eligible=(batchData||[]).filter(b=>b.verified&&Date.parse(b.expires_at)>Date.now()&&Number(b.balance_grams)>Number(b.reserved_grams));modalForm('Выберите урожай со склада',`<div class="room-menu-links">${eligible.map(b=>`<button type="button" onclick="produceListing('${b.id}')">${b.is_simulation?'Демо · ':''}${esc(b.crop)} · ${storageKg(Number(b.balance_grams)-Number(b.reserved_grams))}<span>›</span></button>`).join('')||'<p>Нет свободного урожая с действующим сроком хранения.</p>'}</div>`,()=>{})}
farmViews.add(()=>{if(location.hash!=='#market'||!account||!lifeData)return;const rows=lifeData.listings||[];document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="panel produce-market-shelf"><h2>🧺 Урожай со складов</h2>${rows.length?`<div class="grid">${rows.map(l=>`<article class="panel"><div style="font-size:44px" aria-hidden="true">${storageCropIcon(l.crop)}</div><h3>${esc(l.crop)}</h3>${productRatingBadge(l.quality_score,!!l.is_simulation)}<p>${storageKg(l.grams)} · ${money(l.price_kopecks)} за лот</p><button class="btn light" onclick="showPassport('${l.batch_id}')">Паспорт продукта</button>${l.owner_id===account.id?'<small>Ваше объявление</small>':`<button class="btn" onclick="buyProduce('${l.id}')">Купить демобалансом</button>`}</article>`).join('')}</div>`:'<p>Свежие партии появятся здесь после сбора и размещения на рынке.</p>'}<button class="btn light" onclick="sellStoredProduce()">Продать урожай со склада</button></section>`)});
